  is_internal TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_tc_ticket (ticket_id, hotel_id),
  CONSTRAINT fk_tc_ticket FOREIGN KEY (ticket_id, hotel_id) REFERENCES tickets (id, hotel_id),
  CONSTRAINT fk_tc_user FOREIGN KEY (user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ticket_attachments (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  ticket_id INT UNSIGNED NOT NULL,
  hotel_id INT UNSIGNED NOT NULL,
  stage VARCHAR(20) NOT NULL DEFAULT 'BEFORE',
  disk_path VARCHAR(255) NOT NULL,
  original_name VARCHAR(255) NOT NULL,
  mime VARCHAR(100) NOT NULL,
  size_bytes INT UNSIGNED NOT NULL,
  uploaded_by INT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_tatt_ticket (ticket_id, hotel_id),
  CONSTRAINT chk_tatt_stage CHECK (stage IN ('BEFORE','AFTER','DOCUMENT')),
  CONSTRAINT fk_tatt_ticket FOREIGN KEY (ticket_id, hotel_id) REFERENCES tickets (id, hotel_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Hourly labour rate per technician per hotel, effective-dated
CREATE TABLE technician_rates (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id INT UNSIGNED NOT NULL,
  hotel_id INT UNSIGNED NOT NULL,
  hourly_rate DECIMAL(10,2) NOT NULL,
  effective_from DATE NOT NULL,
  created_by INT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_rate (user_id, hotel_id, effective_from),
  CONSTRAINT fk_rate_user FOREIGN KEY (user_id) REFERENCES users (id),
  CONSTRAINT fk_rate_hotel FOREIGN KEY (hotel_id) REFERENCES hotels (id),
  CONSTRAINT chk_rate_pos CHECK (hourly_rate >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE work_logs (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  ticket_id INT UNSIGNED NOT NULL,
  hotel_id INT UNSIGNED NOT NULL,
  technician_id INT UNSIGNED NOT NULL,
  started_at DATETIME NOT NULL,
  ended_at DATETIME NOT NULL,
  hours DECIMAL(7,2) NOT NULL,
  description TEXT NOT NULL,
  labor_rate DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  labor_cost DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  created_by INT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_wl_ticket (ticket_id, hotel_id),
  KEY idx_wl_tech (technician_id, started_at),
  CONSTRAINT fk_wl_ticket FOREIGN KEY (ticket_id, hotel_id) REFERENCES tickets (id, hotel_id),
  CONSTRAINT fk_wl_tech FOREIGN KEY (technician_id) REFERENCES users (id),
  CONSTRAINT chk_wl_hours CHECK (hours > 0 AND hours <= 24)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ticket_approvals (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  ticket_id INT UNSIGNED NOT NULL,
  hotel_id INT UNSIGNED NOT NULL,
  approval_type VARCHAR(20) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
  amount DECIMAL(14,2) NULL,
  note VARCHAR(1000) NULL,
  requested_by INT UNSIGNED NULL,
  requested_at DATETIME NOT NULL,
  decided_by INT UNSIGNED NULL,
  decided_at DATETIME NULL,
  decision_note VARCHAR(1000) NULL,
  PRIMARY KEY (id),
  KEY idx_tapp_ticket (ticket_id, hotel_id),
  KEY idx_tapp_status (hotel_id, status),
  CONSTRAINT chk_tapp_type CHECK (approval_type IN ('COMPLETION','WORK','PARTS','CONTRACTOR')),
  CONSTRAINT chk_tapp_status CHECK (status IN ('PENDING','APPROVED','REJECTED','CANCELLED')),
  CONSTRAINT fk_tapp_ticket FOREIGN KEY (ticket_id, hotel_id) REFERENCES tickets (id, hotel_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Source: 003_inventory.sql
-- =====================================================================
-- 003 INVENTORY: shared catalogue, per-hotel stock ledger, transfers, PRs
-- Policy: hotel_stock is a cached balance; stock_movements is the ledger.
-- Every balance change MUST insert a stock_movements row in the same tx.
-- =====================================================================

CREATE TABLE part_categories (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  name_th VARCHAR(100) NOT NULL,
  name_en VARCHAR(100) NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_pcat_name (name_th)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE spare_parts (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  sku VARCHAR(40) NOT NULL,
  name VARCHAR(200) NOT NULL,
  category_id INT UNSIGNED NULL,
  description VARCHAR(1000) NULL,
  unit VARCHAR(20) NOT NULL DEFAULT 'ชิ้น',
  supplier_id INT UNSIGNED NULL,
  cost_price DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  min_stock DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  reorder_point DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  image_path VARCHAR(255) NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  is_demo TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_part_sku (sku),
  CONSTRAINT fk_part_cat FOREIGN KEY (category_id) REFERENCES part_categories (id),
  CONSTRAINT fk_part_sup FOREIGN KEY (supplier_id) REFERENCES suppliers (id),
  CONSTRAINT chk_part_cost CHECK (cost_price >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE hotel_stock (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  hotel_id INT UNSIGNED NOT NULL,
  part_id INT UNSIGNED NOT NULL,
  qty_on_hand DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  avg_cost DECIMAL(14,4) NOT NULL DEFAULT 0.0000,
  min_stock DECIMAL(12,2) NULL,
  reorder_point DECIMAL(12,2) NULL,
  bin_location VARCHAR(50) NULL,
  low_stock_notified_at DATETIME NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_stock (hotel_id, part_id),
  CONSTRAINT fk_stock_hotel FOREIGN KEY (hotel_id) REFERENCES hotels (id),
  CONSTRAINT fk_stock_part FOREIGN KEY (part_id) REFERENCES spare_parts (id),
  CONSTRAINT chk_stock_nonneg CHECK (qty_on_hand >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE stock_movements (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  hotel_id INT UNSIGNED NOT NULL,
  part_id INT UNSIGNED NOT NULL,
  movement_type VARCHAR(20) NOT NULL,
  quantity DECIMAL(12,2) NOT NULL,
  unit_cost DECIMAL(14,4) NOT NULL DEFAULT 0.0000,
  total_cost DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  balance_after DECIMAL(12,2) NOT NULL,
  ref_type VARCHAR(20) NULL,
  ref_id BIGINT UNSIGNED NULL,
  reversal_of_id BIGINT UNSIGNED NULL,
  supplier_id INT UNSIGNED NULL,
  note VARCHAR(500) NULL,
  user_id INT UNSIGNED NULL,
  created_at DATETIME NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_sm_reversal (reversal_of_id),
  KEY idx_sm_hotel_part (hotel_id, part_id, created_at),
  KEY idx_sm_ref (ref_type, ref_id),
  KEY idx_sm_type (hotel_id, movement_type, created_at),
  CONSTRAINT chk_sm_type CHECK (movement_type IN ('RECEIVE','ISSUE','RETURN','ADJUSTMENT','TRANSFER_OUT','TRANSFER_IN')),
  CONSTRAINT chk_sm_qty CHECK (quantity <> 0),
  CONSTRAINT fk_sm_hotel FOREIGN KEY (hotel_id) REFERENCES hotels (id),
  CONSTRAINT fk_sm_part FOREIGN KEY (part_id) REFERENCES spare_parts (id),
  CONSTRAINT fk_sm_rev FOREIGN KEY (reversal_of_id) REFERENCES stock_movements (id),
  CONSTRAINT fk_sm_sup FOREIGN KEY (supplier_id) REFERENCES suppliers (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE stock_transfers (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  transfer_no VARCHAR(30) NOT NULL,
  from_hotel_id INT UNSIGNED NOT NULL,
  to_hotel_id INT UNSIGNED NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'REQUESTED',
  note VARCHAR(1000) NULL,
  requested_by INT UNSIGNED NOT NULL,
  requested_at DATETIME NOT NULL,
  approved_by INT UNSIGNED NULL,
  approved_at DATETIME NULL,
  received_by INT UNSIGNED NULL,
  received_at DATETIME NULL,
  closed_by INT UNSIGNED NULL,
  closed_at DATETIME NULL,
  close_reason VARCHAR(500) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_transfer_no (transfer_no),
  KEY idx_tr_from (from_hotel_id, status),
  KEY idx_tr_to (to_hotel_id, status),
  CONSTRAINT chk_tr_status CHECK (status IN ('REQUESTED','IN_TRANSIT','RECEIVED','REJECTED','CANCELLED')),
  CONSTRAINT chk_tr_diff CHECK (from_hotel_id <> to_hotel_id),
  CONSTRAINT fk_tr_from FOREIGN KEY (from_hotel_id) REFERENCES hotels (id),
  CONSTRAINT fk_tr_to FOREIGN KEY (to_hotel_id) REFERENCES hotels (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE stock_transfer_items (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  transfer_id INT UNSIGNED NOT NULL,
  part_id INT UNSIGNED NOT NULL,
  quantity DECIMAL(12,2) NOT NULL,
  unit_cost DECIMAL(14,4) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_tri (transfer_id, part_id),
  CONSTRAINT fk_tri_tr FOREIGN KEY (transfer_id) REFERENCES stock_transfers (id),
  CONSTRAINT fk_tri_part FOREIGN KEY (part_id) REFERENCES spare_parts (id),
  CONSTRAINT chk_tri_qty CHECK (quantity > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ticket_part_usages (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  ticket_id INT UNSIGNED NOT NULL,
  hotel_id INT UNSIGNED NOT NULL,
  part_id INT UNSIGNED NOT NULL,
  quantity DECIMAL(12,2) NOT NULL,
  unit_cost DECIMAL(14,4) NOT NULL,
  total_cost DECIMAL(14,2) NOT NULL,
  movement_id BIGINT UNSIGNED NOT NULL,
  reversal_movement_id BIGINT UNSIGNED NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'ISSUED',
  issued_by INT UNSIGNED NULL,
  created_at DATETIME NOT NULL,
  reversed_by INT UNSIGNED NULL,
  reversed_at DATETIME NULL,
  reverse_reason VARCHAR(500) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_tpu_mv (movement_id),
  KEY idx_tpu_ticket (ticket_id, hotel_id),
  CONSTRAINT chk_tpu_status CHECK (status IN ('ISSUED','REVERSED')),
  CONSTRAINT chk_tpu_qty CHECK (quantity > 0),
  CONSTRAINT fk_tpu_ticket FOREIGN KEY (ticket_id, hotel_id) REFERENCES tickets (id, hotel_id),
  CONSTRAINT fk_tpu_part FOREIGN KEY (part_id) REFERENCES spare_parts (id),
  CONSTRAINT fk_tpu_mv FOREIGN KEY (movement_id) REFERENCES stock_movements (id),
  CONSTRAINT fk_tpu_rmv FOREIGN KEY (reversal_movement_id) REFERENCES stock_movements (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE purchase_requests (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  pr_no VARCHAR(30) NOT NULL,
  hotel_id INT UNSIGNED NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'SUBMITTED',
  supplier_id INT UNSIGNED NULL,
  note VARCHAR(1000) NULL,
  total_amount DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  requested_by INT UNSIGNED NOT NULL,
  requested_at DATETIME NOT NULL,
  approved_by INT UNSIGNED NULL,
  approved_at DATETIME NULL,
  received_by INT UNSIGNED NULL,
  received_at DATETIME NULL,
  reject_reason VARCHAR(500) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_pr_no (pr_no),
  KEY idx_pr_hotel (hotel_id, status),
  CONSTRAINT chk_pr_status CHECK (status IN ('SUBMITTED','APPROVED','REJECTED','RECEIVED','CANCELLED')),
  CONSTRAINT fk_pr_hotel FOREIGN KEY (hotel_id) REFERENCES hotels (id),
  CONSTRAINT fk_pr_sup FOREIGN KEY (supplier_id) REFERENCES suppliers (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE purchase_request_items (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  pr_id INT UNSIGNED NOT NULL,
  part_id INT UNSIGNED NOT NULL,
  quantity DECIMAL(12,2) NOT NULL,
  unit_cost DECIMAL(14,4) NOT NULL,
  total_cost DECIMAL(14,2) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_pri (pr_id, part_id),
  CONSTRAINT fk_pri_pr FOREIGN KEY (pr_id) REFERENCES purchase_requests (id),
  CONSTRAINT fk_pri_part FOREIGN KEY (part_id) REFERENCES spare_parts (id),
  CONSTRAINT chk_pri_qty CHECK (quantity > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Source: 004_preventive_maintenance.sql
-- =====================================================================
-- 004 PREVENTIVE MAINTENANCE
-- Each generated PM work order is backed by a PREVENTIVE ticket so it
-- flows through the same workflow, calendar, costs and KPI logic.
-- UNIQUE(pm_plan_id, due_date) makes cron generation idempotent.
-- =====================================================================

CREATE TABLE pm_plans (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  hotel_id INT UNSIGNED NOT NULL,
  plan_no VARCHAR(30) NOT NULL,
  asset_id INT UNSIGNED NULL,
  category_id INT UNSIGNED NOT NULL,
  priority_id TINYINT UNSIGNED NOT NULL,
  task_name VARCHAR(200) NOT NULL,
  description TEXT NULL,
  frequency VARCHAR(20) NOT NULL,
  interval_days INT UNSIGNED NULL,
  planned_minutes INT UNSIGNED NOT NULL DEFAULT 60,
  assigned_to INT UNSIGNED NULL,
  start_date DATE NOT NULL,
  next_due_date DATE NOT NULL,
  lead_days INT UNSIGNED NOT NULL DEFAULT 0,
  last_generated_due DATE NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  is_demo TINYINT(1) NOT NULL DEFAULT 0,
  created_by INT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_pm_no (plan_no),
  UNIQUE KEY uq_pm_id_hotel (id, hotel_id),
  KEY idx_pm_due (is_active, next_due_date),
  KEY idx_pm_asset (asset_id, hotel_id),
  CONSTRAINT chk_pm_freq CHECK (frequency IN ('DAILY','WEEKLY','MONTHLY','QUARTERLY','SEMIANNUAL','YEARLY','CUSTOM')),
  CONSTRAINT chk_pm_custom CHECK (frequency <> 'CUSTOM' OR (interval_days IS NOT NULL AND interval_days > 0)),
  CONSTRAINT fk_pm_hotel FOREIGN KEY (hotel_id) REFERENCES hotels (id),
  CONSTRAINT fk_pm_asset FOREIGN KEY (asset_id, hotel_id) REFERENCES assets (id, hotel_id),
  CONSTRAINT fk_pm_cat FOREIGN KEY (category_id) REFERENCES maintenance_categories (id),
  CONSTRAINT fk_pm_prio FOREIGN KEY (priority_id) REFERENCES priorities (id),
  CONSTRAINT fk_pm_user FOREIGN KEY (assigned_to) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE pm_checklist_items (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  pm_plan_id INT UNSIGNED NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  label VARCHAR(255) NOT NULL,
  value_type VARCHAR(10) NOT NULL DEFAULT 'CHECK',
  unit VARCHAR(20) NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  KEY idx_pci_plan (pm_plan_id, sort_order),
  CONSTRAINT chk_pci_type CHECK (value_type IN ('CHECK','NUMBER','TEXT')),
  CONSTRAINT fk_pci_plan FOREIGN KEY (pm_plan_id) REFERENCES pm_plans (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE pm_work_orders (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  hotel_id INT UNSIGNED NOT NULL,
  pm_plan_id INT UNSIGNED NOT NULL,
  ticket_id INT UNSIGNED NOT NULL,
  due_date DATE NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'OPEN',
  completed_at DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_pmwo_due (pm_plan_id, due_date),
  UNIQUE KEY uq_pmwo_ticket (ticket_id),
  KEY idx_pmwo_hotel (hotel_id, due_date),
  CONSTRAINT chk_pmwo_status CHECK (status IN ('OPEN','COMPLETED','CANCELLED')),
  CONSTRAINT fk_pmwo_plan FOREIGN KEY (pm_plan_id, hotel_id) REFERENCES pm_plans (id, hotel_id),
  CONSTRAINT fk_pmwo_ticket FOREIGN KEY (ticket_id, hotel_id) REFERENCES tickets (id, hotel_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE pm_checklist_results (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  pm_work_order_id INT UNSIGNED NOT NULL,
  checklist_item_id INT UNSIGNED NOT NULL,
  is_done TINYINT(1) NOT NULL DEFAULT 0,
  value_text VARCHAR(255) NULL,
  comment VARCHAR(500) NULL,
  is_defect TINYINT(1) NOT NULL DEFAULT 0,
  recorded_by INT UNSIGNED NULL,
  recorded_at DATETIME NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_pcr (pm_work_order_id, checklist_item_id),
  CONSTRAINT fk_pcr_wo FOREIGN KEY (pm_work_order_id) REFERENCES pm_work_orders (id),
  CONSTRAINT fk_pcr_item FOREIGN KEY (checklist_item_id) REFERENCES pm_checklist_items (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Source: 005_finance.sql
-- =====================================================================
-- 005 FINANCE: single cost ledger + budgets
-- Cost recognition: maintenance cost is recognised when parts are
-- CONSUMED on a ticket (PART_USAGE) or labour is LOGGED (WORK_LOG), or a
-- MANUAL expense (contractor/replacement/other) is APPROVED.
-- Inventory purchases (stock RECEIVE) are NOT maintenance costs.
-- =====================================================================

CREATE TABLE cost_categories (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  code VARCHAR(20) NOT NULL,
  name_th VARCHAR(100) NOT NULL,
  name_en VARCHAR(100) NOT NULL,
  is_system TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uq_ccat_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE cost_entries (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  hotel_id INT UNSIGNED NOT NULL,
  ticket_id INT UNSIGNED NULL,
  asset_id INT UNSIGNED NULL,
  category_id INT UNSIGNED NOT NULL,
  source VARCHAR(20) NOT NULL DEFAULT 'MANUAL',
  source_id BIGINT UNSIGNED NULL,
  description VARCHAR(500) NOT NULL,
  quantity DECIMAL(12,2) NOT NULL DEFAULT 1.00,
  unit_cost DECIMAL(14,4) NOT NULL,
  total_cost DECIMAL(14,2) NOT NULL,
  expense_date DATE NOT NULL,
  supplier_id INT UNSIGNED NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
  approved_by INT UNSIGNED NULL,
  approved_at DATETIME NULL,
  reject_reason VARCHAR(500) NULL,
  document_path VARCHAR(255) NULL,
  document_name VARCHAR(255) NULL,
  document_mime VARCHAR(100) NULL,
  is_demo TINYINT(1) NOT NULL DEFAULT 0,
  created_by INT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_cost_source (source, source_id),
  KEY idx_cost_hotel_date (hotel_id, expense_date),
  KEY idx_cost_ticket (ticket_id, hotel_id),
  KEY idx_cost_asset (asset_id, hotel_id),
  KEY idx_cost_status (hotel_id, status),
  CONSTRAINT chk_cost_status CHECK (status IN ('PENDING','APPROVED','REJECTED','VOID')),
  CONSTRAINT chk_cost_source CHECK (source IN ('MANUAL','PART_USAGE','WORK_LOG')),
  CONSTRAINT chk_cost_nonneg CHECK (total_cost >= 0),
  CONSTRAINT fk_cost_hotel FOREIGN KEY (hotel_id) REFERENCES hotels (id),
  CONSTRAINT fk_cost_ticket FOREIGN KEY (ticket_id, hotel_id) REFERENCES tickets (id, hotel_id),
  CONSTRAINT fk_cost_asset FOREIGN KEY (asset_id, hotel_id) REFERENCES assets (id, hotel_id),
  CONSTRAINT fk_cost_cat FOREIGN KEY (category_id) REFERENCES cost_categories (id),
  CONSTRAINT fk_cost_sup FOREIGN KEY (supplier_id) REFERENCES suppliers (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- month NULL = annual budget; category_id NULL = all categories
CREATE TABLE budgets (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  hotel_id INT UNSIGNED NOT NULL,
  year SMALLINT UNSIGNED NOT NULL,
  month TINYINT UNSIGNED NULL,
  category_id INT UNSIGNED NULL,
  amount DECIMAL(14,2) NOT NULL,
  note VARCHAR(500) NULL,
  month_key TINYINT UNSIGNED AS (IFNULL(month, 0)) STORED,
  category_key INT UNSIGNED AS (IFNULL(category_id, 0)) STORED,
  created_by INT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_budget (hotel_id, year, month_key, category_key),
  CONSTRAINT chk_budget_month CHECK (month IS NULL OR (month BETWEEN 1 AND 12)),
  CONSTRAINT chk_budget_amt CHECK (amount >= 0),
  CONSTRAINT fk_budget_hotel FOREIGN KEY (hotel_id) REFERENCES hotels (id),
  CONSTRAINT fk_budget_cat FOREIGN KEY (category_id) REFERENCES cost_categories (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Source: 006_notifications.sql
-- =====================================================================
-- 006 NOTIFICATIONS: LINE destinations, rules, durable queue, logs
-- =====================================================================

-- A LINE group discovered via webhook (join/message). Must be explicitly
-- BOUND to a hotel by an administrator before it receives notifications.
CREATE TABLE line_destinations (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  hotel_id INT UNSIGNED NULL,
  group_id VARCHAR(64) NOT NULL,
  display_name VARCHAR(150) NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'DISCOVERED',
  bound_by INT UNSIGNED NULL,
  bound_at DATETIME NULL,
  discovered_at DATETIME NOT NULL,
  last_event_at DATETIME NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_line_group (group_id),
  KEY idx_line_hotel (hotel_id, status),
  CONSTRAINT chk_line_status CHECK (status IN ('DISCOVERED','BOUND','DISABLED','LEFT')),
  CONSTRAINT fk_line_hotel FOREIGN KEY (hotel_id) REFERENCES hotels (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- hotel_id NULL = group default. Hotel row overrides default.
CREATE TABLE notification_rules (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  hotel_id INT UNSIGNED NULL,
  event_type VARCHAR(50) NOT NULL,
  is_enabled TINYINT(1) NOT NULL DEFAULT 1,
  hotel_key INT UNSIGNED AS (IFNULL(hotel_id, 0)) STORED,
  updated_by INT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_nrule (hotel_key, event_type),
  CONSTRAINT fk_nrule_hotel FOREIGN KEY (hotel_id) REFERENCES hotels (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE notification_queue (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  hotel_id INT UNSIGNED NULL,
  event_type VARCHAR(50) NOT NULL,
  channel VARCHAR(20) NOT NULL DEFAULT 'LINE',
  destination_id INT UNSIGNED NULL,
  dedupe_key VARCHAR(191) NOT NULL,
  payload LONGTEXT NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
  attempts INT UNSIGNED NOT NULL DEFAULT 0,
  max_attempts INT UNSIGNED NOT NULL DEFAULT 5,
  next_attempt_at DATETIME NOT NULL,
  locked_at DATETIME NULL,
  last_error VARCHAR(1000) NULL,
  sent_at DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_nq_dedupe (dedupe_key),
  KEY idx_nq_pending (status, next_attempt_at),
  KEY idx_nq_hotel (hotel_id, created_at),
  CONSTRAINT chk_nq_status CHECK (status IN ('PENDING','PROCESSING','SENT','FAILED','DEAD','SKIPPED')),
  CONSTRAINT fk_nq_dest FOREIGN KEY (destination_id) REFERENCES line_destinations (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE notification_logs (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  queue_id BIGINT UNSIGNED NOT NULL,
  attempt_no INT UNSIGNED NOT NULL,
  transport VARCHAR(20) NOT NULL,
  http_status SMALLINT NULL,
  success TINYINT(1) NOT NULL,
  response_excerpt VARCHAR(1000) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_nl_queue (queue_id),
  CONSTRAINT fk_nl_queue FOREIGN KEY (queue_id) REFERENCES notification_queue (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Webhook de-duplication (LINE may redeliver events). Message text is NOT stored.
CREATE TABLE line_webhook_events (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  webhook_event_id VARCHAR(64) NOT NULL,
  event_type VARCHAR(30) NOT NULL,
  source_type VARCHAR(20) NULL,
  group_id VARCHAR(64) NULL,
  received_at DATETIME NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_lwe (webhook_event_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Source: 007_pm_checklist_snapshots.sql
-- Freeze each generated work order's inspection definition. Editing a PM plan
-- must never rewrite the meaning of historical inspection results.
CREATE TABLE pm_work_order_checklist (
  pm_work_order_id INT UNSIGNED NOT NULL,
  checklist_item_id INT UNSIGNED NOT NULL,
  label VARCHAR(255) NOT NULL,
  value_type VARCHAR(10) NOT NULL,
  unit VARCHAR(20) NULL,
  sort_order INT NOT NULL DEFAULT 0,
  PRIMARY KEY (pm_work_order_id, checklist_item_id),
  CONSTRAINT fk_pwoc_wo FOREIGN KEY (pm_work_order_id) REFERENCES pm_work_orders(id),
  CONSTRAINT fk_pwoc_item FOREIGN KEY (checklist_item_id) REFERENCES pm_checklist_items(id),
  CONSTRAINT chk_pwoc_type CHECK (value_type IN ('CHECK','NUMBER','TEXT'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Existing work orders can only be backfilled from their current definitions.
-- Future orders receive a snapshot inside their generation transaction.
INSERT INTO pm_work_order_checklist (pm_work_order_id,checklist_item_id,label,value_type,unit,sort_order)
SELECT w.id,i.id,i.label,i.value_type,i.unit,i.sort_order
FROM pm_work_orders w JOIN pm_checklist_items i ON i.pm_plan_id=w.pm_plan_id
WHERE i.is_active=1 OR EXISTS (SELECT 1 FROM pm_checklist_results r WHERE r.pm_work_order_id=w.id AND r.checklist_item_id=i.id);


-- Source: 008_public_repairs.sql
-- Public intake metadata stays private; no anonymous ticket lookup is provided.
CREATE TABLE public_repair_submissions (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  ticket_id INT UNSIGNED NOT NULL,
  submission_hash CHAR(64) NOT NULL,
  ip_hash CHAR(64) NOT NULL,
  reporter_kind VARCHAR(10) NOT NULL,
  contact VARCHAR(150) NULL,
  created_at DATETIME NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_public_submission (submission_hash),
  UNIQUE KEY uq_public_ticket (ticket_id),
  KEY idx_public_rate (ip_hash, created_at),
  CONSTRAINT fk_public_ticket FOREIGN KEY (ticket_id) REFERENCES tickets(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


